from pathlib import Path
import json,hashlib,datetime
def load(name):return json.loads(Path('livrables/preuves',name).read_text(encoding='utf-8-sig'))
p=load('performances.json');i=load('integration.json');b=load('navigateur.json');r=load('restauration.json');j=load('parcours.json');clean=load('installation-propre.json');http=load('http.json')
rows=['# Rapport de performances','\nMesures réelles locales, moteur '+p['engine']+', PHP '+p['php']+'. Machine : voir livrables/preuves/machine.json. Buffer pool 128 Mio, isolation READ COMMITTED. Le temps publié est un aller-retour PDO avec récupération des résultats, pas un temps CPU serveur isolé.','\nProtocole : chauffe puis dix exécutions sur le même jeu et les mêmes paramètres, horloge hrtime. Les résultats bruts, EXPLAIN, index et volumes exhaustifs sont dans livrables/preuves/performances.json. Aucune charge utilisateur simultanée contrôlée n’a été appliquée pendant les mesures ; dispersion et contexte local à prendre en compte.','\n| Requête | Médiane ms | Min ms | Max ms | Lignes |\n|---|---:|---:|---:|---:|']
for k,q in p['queries'].items():rows.append(f'| {k} | {q["median_ms"]:.3f} | {q["min_ms"]:.3f} | {q["max_ms"]:.3f} | {q["rows"]} |')
rows+=['\n## Jeu mesuré',f'{p["volumes"]["truck_visit"]} passages, {p["volumes"]["visit_event"]} événements, {p["volumes"]["receipt_line"]} lignes de réception, {p["volumes"]["stock_movement"]} mouvements, {p["volumes"]["audit_log"]} entrées d’audit. Graine 70, référence 22/10/2026. Stock non négatif, capacités et transferts conservatifs contrôlés. Les lignes volumétriques sont simulées par SQL sur une base dédiée, pas saisies dans le navigateur.','\n## Comparaison contrôlée',f'Index changé : {p["comparison"]["changed"]}. Lecture avant {p["comparison"]["before"]["median_ms"]:.3f} ms, après {p["comparison"]["after"]["median_ms"]:.3f} ms. Index quai/état/début/fin adapté aux filtres du planning. Plans complets avant et après dans le JSON.']
if 'write_before' in p['comparison']:
 rows.append(f'Écriture : INSERT de rendez-vous avec trigger puis ROLLBACK, une chauffe et dix répétitions ; avant {p["comparison"]["write_before"]["median_ms"]:.3f} ms, après {p["comparison"]["write_after"]["median_ms"]:.3f} ms. Ce protocole inclut journal et rollback ; il ne mesure pas un débit durable de commits. Une petite différence inférieure à la dispersion ne permet pas de conclure à un coût universel.')
rows+=['\n## Temps HTTP distincts','Démonstration : un appel de chauffe puis dix réponses authentifiées par route ; temps Playwright request jusqu’à réception du corps, sans les ressources CSS/JS et sans exécution/rendu du navigateur. Jeu petit, donc non comparable directement aux mesures volumétriques PDO.','\n| Page | Médiane ms | Min–max ms |\n|---|---:|---|']
for key,q in http.items():rows.append(f'| {key} | {q["median_ms"]:.3f} | {q["min_ms"]:.3f}–{q["max_ms"]:.3f} |')
rows+=['\n## Analyse','Les vues de passages agrègent encore l’ensemble de l’historique avant certains filtres : elles dominent la durée. Le verrou global privilégie la compréhension et la sûreté ; une vraie mesure de débit concurrent serait nécessaire avant de le remplacer par des verrous par ressource. Les FK/PK, jointures et index de dates sont justifiés par les accès réels. Aucun partitionnement ou réplication artificiel.','\n## SQL et paramètres']
for key,q in p['queries'].items():rows += ['\n### '+key,'```sql\n'+q['sql']+';\n```','Paramètres ordonnés : `'+json.dumps(q['params'],ensure_ascii=False)+'`.','Index/plans : se reporter à l’entrée correspondante du JSON brut ; les métadonnées complètes y sont conservées.']
Path('docs/performances.md').write_text('\n'.join(rows),encoding='utf-8')
tests=['# Recette exécutée','\nTrois niveaux complémentaires : services et contraintes SQL ; pages/contrôles navigateur ; parcours métier complet par formulaires. Chaque résultat est produit par un script livré, sans capture inventée.',f'\n- Intégration : **{i["passed"]} réussis, {i["failed"]} échec** (tests/integration.php).',f'- Navigateur Edge : **{b["passed"]} réussis, {b["failed"]} échec** (tests/browser.cjs).',f'- Parcours complet : **{j["passed"]} étapes réussies**, {j["failed"]} échec (tests/parcours.cjs sur serveur de test distinct).',f'- Copie propre : nouvelle configuration et nouveau compte SQL ; **{len(clean["authenticated_routes"])} routes authentifiées** vérifiées.','- Sauvegarde/restauration : 40 tables par comptes et checksums, 116 triggers et 2 procédures ; historisation réellement déclenchée dans la copie.','\n## Invariants et scénarios','| Règle | Preuve exécutée |\n|---|---|','| R01 | Chevauchement, modification conflictuelle, adjacence, course à deux connexions |','| R02 | Type de quai, indisponibilité, fermeture sur réservation refusée ; froid/ADR dans seed et parcours |','| R03 | Course à deux affectations : un seul quai occupé |','| R04 | Transition impossible et horodatage rétrograde refusés |','| R05 | Rejeu de réception sans nouvelle entrée |','| R06 | Négatif refusé ; deux commandes tentent de réserver le même disponible |','| R07 | Transfert conserve la somme de la fraction |','| R08 | Zone incompatible et deux rangements concurrents en capacité limitée |','| R09 | Disponible bloqué/périmé nul ; avaries conservées hors stock |','| R10 | Deux commandes du même lot, liens vers camion, double expédition refusée |','| R11 | Journal automatique auteur/date/opération ; droits SQL et immuabilité |','| R12 | Réception annulée après première fraction, transfert sans débit partiel, préparation insuffisante sans réservation, rendez-vous modifié annulé |','\n## Résultats d’intégration détaillés']
tests += ['- '+x for x in i['successes']]
tests+=['\n## Limites de la preuve','Les tests sont locaux et ne constituent pas une validation sur appareil physique, un autre moteur SQL ou une infrastructure publique. Les scénarios d’erreur sont dans une base dédiée ; la démo reste lisible. Les impressions ont été rendues en PDF ; le rapport et les captures sont revus visuellement. Les procédures de reprise sont dans le README.']
Path('docs/recette.md').write_text('\n'.join(tests),encoding='utf-8')
