data=[('F01','UC01','user_account','Auth, utilisateurs','Rôles, inscription, CSRF, HTTP direct','7'),('F02','UC02','carrier, driver, vehicle, équipements et associations','Catalog / référentiels','CRUD SQL + navigateur, 39 rubriques visitées','7'),('F03','UC03','dock, appointment, dock_downtime','Planning / Warehouse','R01, R02, deux connexions','8'),('F04','UC04','truck_visit, visit_event','Poste de garde / transitions','R03, R04, parcours sans rendez-vous','8'),('F05','UC05','supplier_notice, notice_line, receipt, receipt_line, receipt_item','Réception et rangement','R05, R08, R12, avarie / manquant / excédent','9'),('F06','UC06','article, lot, structure, stock_movement','Stock, propositions, transfert et ajustement','R06–R09, concurrence capacité, filtres','9'),('F07','UC07–08','customer_order, order_line, pick, package, package_pick, shipment','Commandes, colis, expédition et documents','FEFO, R10, parcours 31 étapes, PDFs','10'),('F08','UC09–10','vues de stock, visites, écarts et procédures','Trace, tableaux, graphes, états et CSV','Oracles, filtres CSV et graphiques, HTTP','10, 12–15')]
for f,uc,t,screen,test,report in data:matrix.append(f'| {f} | {uc} | {t} | {screen} | {test} | {report} | réalisé et testé |')
